        coeffs = bracket_coeffs(1, 'H_1', 'H_2')
        assert nonzero(coeffs) == {}

    def test_even_selfbracket_zero(self):
        # [X, X} = 0 for even X
        for lbl in ['H_1', 'H_2', 'E_2del1_p', 'E_2del1_m']:
