python3 -c "
import json
from fractions import Fraction

print('=== Schema 1 / Schema 2 Consistency Check ===')
overall = True

for n in [1, 2, 3]:
    s1 = json.load(open(f'data/C_{n}_structure.json'))
    s2 = json.load(open(f'data/C_{n}_gamma.json'))

    s1_basis = set(s1['basis']['even'] + s1['basis']['odd'])
    valid_targets = s1_basis | {'K'}

    failures = []

    # Algebra metadata
    if s2['algebra']['family'] != s1['algebra']['family']: failures.append('family mismatch')
    if s2['algebra']['n'] != n: failures.append('n mismatch')
    if s2['algebra']['dimension']['even'] != s1['algebra']['dimension']['even']: failures.append('even dim mismatch')
    if s2['algebra']['dimension']['odd'] != s1['algebra']['dimension']['odd']: failures.append('odd dim mismatch')

    # gb_matrix
    if s2['gb_matrix']['count'] != 4 * n: failures.append('gb count mismatch')
    if len(s2['gb_matrix']['parameters']) != 4 * n: failures.append('gb param list length mismatch')

    # Sign convention
    if s2['sign_convention']['sign'] != '-1': failures.append('sign convention not -1')

    # All references in gamma valid
    gb_labels_def = {p['label'] for p in s2['gb_matrix']['parameters']}
    bad_entries = [e for e in s2['gamma']
                   if e['X'] not in s1_basis or e['Y'] not in s1_basis
                   or e['Z'] not in valid_targets or e['gb_label'] not in gb_labels_def]
    if bad_entries: failures.append(f'{len(bad_entries)} bad gamma entry references')

    # All coefficients non-zero
    zero_coeffs = [e for e in s2['gamma'] if Fraction(e['coeff']) == 0]
    if zero_coeffs: failures.append(f'{len(zero_coeffs)} zero coefficients')

    status = 'PASS' if not failures else 'FAIL'
    if failures: overall = False
    print(f'  n={n}: {status}  entries={len(s2[\"gamma\"])}  failures={failures}')

print()
print('OVERALL:', 'ALL CHECKS PASSED' if overall else 'SOME CHECKS FAILED')
" 2>&1

